"use client";

import {
  type ButtonHTMLAttributes,
  createContext,
  type HTMLAttributes,
  type KeyboardEvent,
  use,
  useCallback,
  useId,
  useState,
} from "react";
import { cx } from "../utils/cx";
import { ChevronDownIcon } from "../icons/interface";

type AccordionContextValue = {
  isOpen: (value: string) => boolean;
  toggle: (value: string) => void;
  base: string;
  headingLevel: 2 | 3 | 4;
};
const AccordionContext = createContext<AccordionContextValue | null>(null);
const ItemContext = createContext<{ value: string; disabled?: boolean } | null>(null);

function useAccordion(part: string) {
  const ctx = use(AccordionContext);
  const item = use(ItemContext);
  if (!ctx || !item) throw new Error(`<${part}> must be inside <AccordionItem> inside <Accordion>`);
  return { ...ctx, ...item };
}

type Common = Omit<HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> & {
  /** Heading level of each trigger's wrapper, for the page outline. Default 3. */
  headingLevel?: 2 | 3 | 4;
};
export type AccordionProps = Common &
  (
    | {
        type?: "single";
        value?: string;
        defaultValue?: string;
        onValueChange?: (value: string) => void;
        collapsible?: boolean;
      }
    | {
        type: "multiple";
        value?: string[];
        defaultValue?: string[];
        onValueChange?: (value: string[]) => void;
        collapsible?: never;
      }
  );

/**
 * Stacked sections that open one at a time (`type="single"`, collapsible by default) or independently
 * (`type="multiple"`). Up/Down, Home and End move between the headers. Each panel animates its height.
 */
export function Accordion(props: AccordionProps) {
  const { type = "single", headingLevel = 3, className, onKeyDown, ...more } = props;
  const { value: _v, defaultValue: _d, onValueChange: _o, collapsible: _c, ...rest } = more as Record<string, unknown>;
  const multiple = type === "multiple";
  const collapsible = multiple ? true : (props as { collapsible?: boolean }).collapsible !== false;
  const initial = (props as { defaultValue?: string | string[] }).defaultValue;
  const [inner, setInner] = useState<string[]>(() =>
    initial === undefined ? [] : Array.isArray(initial) ? initial : [initial],
  );
  const controlled = (props as { value?: string | string[] }).value;
  const open = controlled === undefined ? inner : Array.isArray(controlled) ? controlled : [controlled];
  const onValueChange = (props as { onValueChange?: (v: never) => void }).onValueChange;
  const base = useId();
  const toggle = useCallback(
    (value: string) => {
      const isOpen = open.includes(value);
      let next: string[];
      if (multiple) next = isOpen ? open.filter((v) => v !== value) : [...open, value];
      else next = isOpen ? (collapsible ? [] : open) : [value];
      if (controlled === undefined) setInner(next);
      onValueChange?.((multiple ? next : (next[0] ?? "")) as never);
    },
    [open, multiple, collapsible, controlled, onValueChange],
  );
  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    (onKeyDown as ((e: KeyboardEvent<HTMLDivElement>) => void) | undefined)?.(e);
    if (e.defaultPrevented || !["ArrowDown", "ArrowUp", "Home", "End"].includes(e.key)) return;
    const triggers = Array.from(
      e.currentTarget.querySelectorAll<HTMLButtonElement>("[data-hm-accordion-trigger]:not(:disabled)"),
    );
    const i = triggers.indexOf(document.activeElement as HTMLButtonElement);
    if (i < 0) return;
    const to =
      e.key === "Home"
        ? 0
        : e.key === "End"
          ? triggers.length - 1
          : (i + (e.key === "ArrowDown" ? 1 : -1) + triggers.length) % triggers.length;
    e.preventDefault();
    triggers[to]?.focus();
  };
  return (
    <AccordionContext value={{ isOpen: (v) => open.includes(v), toggle, base, headingLevel }}>
      <div {...(rest as HTMLAttributes<HTMLDivElement>)} className={cx("hm-accordion", className)} onKeyDown={onKey} />
    </AccordionContext>
  );
}

export type AccordionItemProps = HTMLAttributes<HTMLDivElement> & { value: string; disabled?: boolean };

export function AccordionItem({ value, disabled, className, ...rest }: AccordionItemProps) {
  const ctx = use(AccordionContext);
  if (!ctx) throw new Error("<AccordionItem> must be inside <Accordion>");
  return (
    <ItemContext value={{ value, disabled }}>
      <div
        {...rest}
        className={cx("hm-accordion-item", className)}
        data-state={ctx.isOpen(value) ? "open" : "closed"}
      />
    </ItemContext>
  );
}

export function AccordionTrigger({ className, children, onClick, ...rest }: ButtonHTMLAttributes<HTMLButtonElement>) {
  const { isOpen, toggle, base, headingLevel, value, disabled } = useAccordion("AccordionTrigger");
  const open = isOpen(value);
  const Heading = `h${headingLevel}` as "h3";
  return (
    <Heading className="hm-accordion-heading">
      <button
        {...rest}
        type="button"
        id={`${base}-trigger-${value}`}
        aria-expanded={open}
        aria-controls={`${base}-panel-${value}`}
        disabled={disabled}
        data-hm-accordion-trigger=""
        data-state={open ? "open" : "closed"}
        className={cx("hm-accordion-trigger", className)}
        onClick={(e) => {
          onClick?.(e);
          if (!e.defaultPrevented) toggle(value);
        }}
      >
        <span>{children}</span>
        <ChevronDownIcon className="hm-accordion-chevron" size={14} />
      </button>
    </Heading>
  );
}

export function AccordionContent({ className, children, ...rest }: HTMLAttributes<HTMLDivElement>) {
  const { isOpen, base, value } = useAccordion("AccordionContent");
  const open = isOpen(value);
  return (
    <div
      {...rest}
      id={`${base}-panel-${value}`}
      role="region"
      aria-labelledby={`${base}-trigger-${value}`}
      className={cx("hm-collapsible-content hm-accordion-content", className)}
      data-state={open ? "open" : "closed"}
      inert={open ? undefined : true}
    >
      <div className="hm-collapsible-inner">{children}</div>
    </div>
  );
}
